         q('eq-2', 1, '옳은 식은?', '10 + 5 = 12 + 3', [('10 + 5 = 12 + 5', 'eq'), ('10 + 5 = 10 + 6', 'eq'), ('10 + 5 = 15 + 3', 'eq')], '양쪽을 각각 계산해요.', '10 + 5 = 15, 12 + 3 = 15로 같아요.', '첫 단계: 왼쪽 10 + 5를 계산해요'),
         q('eq-3', 1, '□에 알맞은 수를 구하세요. 20 + 7 = 17 + □', str(20 + 7 - 17), [('27', 'eq'), ('7', 'calc'), ('44', 'eq')], '왼쪽은 27이에요.', '17 + 10 = 27이므로 10이에요.', '첫 단계: 왼쪽을 계산해요'),
         q('eq-4', 2, '□에 알맞은 수를 구하세요. 4 × 6 = 8 × □', str(4 * 6 // 8), [('24', 'eq'), ('12', 'calc'), ('6', 'calc')], '4가 2배인 8이 되었어요.', '8 × 3 = 24이므로 3이에요.', '첫 단계: 4 × 6을 계산해요'),
         q('eq-5', 2, '옳지 않은 식은?', '30 − 8 = 32 − 6', [('30 − 8 = 32 − 10', 'eq'), ('30 − 8 = 20 + 2', 'eq'), ('30 − 8 = 11 × 2', 'eq')], '양쪽을 각각 계산해 봐요.', '30 − 8 = 22, 32 − 6 = 26이므로 같지 않아요.', '첫 단계: 30 − 8을 계산해요'),
         q('eq-6', 2, '□에 알맞은 수를 구하세요. 45 − 15 = 50 − □', str(50 - (45 - 15)), [('10', 'eq'), ('30', 'eq'), ('5', 'calc')], '빼어지는 수가 5 커졌어요.', '왼쪽은 30, 50 − 20 = 30이므로 20이에요.', '첫 단계: 왼쪽을 계산해요'),
